const int LED = 9;
const int SENSOR = A0;

void setup() {
    pinMode(LED, OUTPUT);
    Serial.begin(115200);
}

void loop() {
    int raw = analogRead(SENSOR);          // 0-1023 på en 10-bitars ADC
    int brightness = map(raw, 0, 1023, 0, 255);
    analogWrite(LED, brightness);          // PWM: starkare ljus när sensorn ger mer
    Serial.println(raw);
    delay(50);
}
